const body = $input.first().json.body || $input.first().json || {};
const appUrl = String($env.EXPORTFLOW_APP_URL || '').replace(/\/+$/, '');
const campaignId = body.campaign_id || body.campaignId;
if (!appUrl) throw new Error('Missing EXPORTFLOW_APP_URL in n8n environment.');
if (!campaignId) throw new Error('campaign_id is required.');
return [{ json: { appUrl, campaign_id: campaignId, secret: $env.N8N_WEBHOOK_SECRET || '', gemini_key: $env.GEMINI_API_KEY || '', gemini_model: $env.GEMINI_MODEL || 'gemini-3-flash-preview' } }];

const cfg = $('Prepare Generate Request').first().json;
const context = $input.first().json;
if (!cfg.gemini_key) throw new Error('Missing GEMINI_API_KEY in n8n environment.');
const prompt = [
  'You are building a B2B cold outreach sequence for ExportFlow.',
  'Return JSON only with keys: strategy, initial_template, followup_1_template, followup_2_template, sample_personalized_emails, safety_notes.',
  'The user will approve templates and samples before launch.',
  'Personalize using lead evidence. Do not invent fake facts.',
  'Keep copy concise, businesslike, and aligned with the requested tone.',
  '',
  `Context JSON: ${JSON.stringify(context)}`
].join('\n');
return [{ json: { ...cfg, context, prompt } }];

const cfg = $('Prepare Gemini Template Prompt').first().json;
const payload = $input.first().json;
const text = payload?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const cleaned = String(text).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
let generated;
try { generated = JSON.parse(cleaned); } catch { generated = { raw_text: text }; }
return [{ json: { appUrl: cfg.appUrl, secret: cfg.secret, campaign_id: cfg.campaign_id, generated } }];

const body = $input.first().json.body || $input.first().json || {};
const appUrl = String($env.EXPORTFLOW_APP_URL || '').replace(/\/+$/, '');
const campaignId = body.campaign_id || body.campaignId;
if (!appUrl) throw new Error('Missing EXPORTFLOW_APP_URL in n8n environment.');
if (!campaignId) throw new Error('campaign_id is required.');
return [{ json: { appUrl, campaign_id: campaignId, secret: $env.N8N_WEBHOOK_SECRET || '' } }];

const appUrl = String($env.EXPORTFLOW_APP_URL || '').replace(/\/+$/, '');
if (!appUrl) throw new Error('Missing EXPORTFLOW_APP_URL in n8n environment.');
return [{ json: { appUrl, secret: $env.N8N_WEBHOOK_SECRET || '', gemini_key: $env.GEMINI_API_KEY || '', gemini_model: $env.GEMINI_MODEL || 'gemini-3-flash-preview', batch_limit: Number($env.EXPORTFLOW_SEND_BATCH_LIMIT || 5), test_mode: String($env.EXPORTFLOW_TEST_MODE || 'true').toLowerCase() !== 'false', test_recipient: $env.EXPORTFLOW_TEST_RECIPIENT || 'ibrahimshkeel1@gmail.com' } }];

const cfg = $('Prepare Due Messages Request').first().json;
const payload = $input.first().json;
const messages = Array.isArray(payload.messages) ? payload.messages : [];
return messages.map((message) => ({ json: { ...cfg, message } }));

const item = $json;
if (!item.gemini_key) throw new Error('Missing GEMINI_API_KEY in n8n environment.');
const message = item.message || {};
const lead = message.lead || {};
const campaign = message.campaign || {};
const prompt = [
  'Write one B2B outreach email.',
  'Return JSON only with keys: subject, body_html, body_text, first_name_used, personalization_notes.',
  `Sequence step: ${message.step || 'initial'}`,
  `Tone: ${campaign.tone || 'professional'}`,
  `CTA: ${campaign.cta || 'reply if interested'}`,
  'Use previous email context for follow-ups so the sequence sounds consistent.',
  'Do not invent facts. Use scraper evidence only.',
  '',
  `Context JSON: ${JSON.stringify({ lead, campaign, previous_email: message.previous_email || null, approved_templates: message.approved_templates || null })}`
].join('\n');
return [{ json: { ...item, prompt } }];

function cleanHeader(value) { return String(value || '').replace(/[\r\n]+/g, ' ').trim(); }
function escapeHtml(value) { return String(value || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function base64url(value) { return Buffer.from(value, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, ''); }
const geminiItems = $input.all();
const preparedItems = $('Prepare Gemini Personalization Prompt').all();
return geminiItems.map((geminiItem, index) => {
  const prepared = preparedItems[index].json;
  const message = prepared.message || {};
  const lead = message.lead || {};
  const campaign = message.campaign || {};
  const sender = message.sender || {};
  const payload = geminiItem.json;
  const text = payload?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  const cleaned = String(text).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  let generated;
  try { generated = JSON.parse(cleaned); } catch { generated = { subject: 'Quick question', body_html: `<p>${escapeHtml(text)}</p>`, raw_text: text }; }
  const subject = cleanHeader(generated.subject || message.subject || `Quick question for ${lead.company_name || 'your team'}`);
  const originalTo = lead.email || lead.original_email || message.original_to || '';
  const recipient = prepared.test_mode || message.test_mode ? prepared.test_recipient : originalTo;
  const fromEmail = cleanHeader(sender.email || message.gmail_from_email || message.sender_email || message.user_email || '');
  const senderName = cleanHeader(sender.name || campaign.sender_name || 'ExportFlow');
  let bodyHtml = generated.body_html || `<p>${escapeHtml(generated.body_text || '')}</p>`;
  if (prepared.test_mode || message.test_mode) {
    bodyHtml = `<p><strong>TEST MODE - not sent to lead.</strong></p><p>Original lead recipient: ${escapeHtml(originalTo)}</p><hr>${bodyHtml}`;
  }
  if (!recipient) throw new Error('No recipient email available.');
  if (!fromEmail) throw new Error('No Gmail sender email available.');
  if (!message.gmail_access_token) throw new Error('No Gmail access token supplied by app.');
  const mime = [`From: ${senderName} <${fromEmail}>`, `To: ${recipient}`, `Subject: ${subject}`, 'MIME-Version: 1.0', 'Content-Type: text/html; charset=UTF-8', '', bodyHtml].join('\r\n');
  return { json: { ...prepared, message_id: message.message_id || message.id, campaign_id: message.campaign_id, gmail_access_token: message.gmail_access_token, raw: base64url(mime), subject, body_html: bodyHtml, generated, to_email: recipient, original_to_email: originalTo, send_status: prepared.test_mode || message.test_mode ? 'test_sent' : 'sent' } };
});

const gmailItems = $input.all();
const builtItems = $('Build Gmail API Message').all();
return gmailItems.map((gmailItem, index) => {
  const built = builtItems[index].json;
  const gmail = gmailItem.json;
  return { json: { appUrl: built.appUrl, secret: built.secret, message_id: built.message_id, campaign_id: built.campaign_id, status: built.send_status, gmail_message_id: gmail.id || null, gmail_thread_id: gmail.threadId || null, to_email: built.to_email, original_to_email: built.original_to_email, subject: built.subject, body_html: built.body_html, generated: built.generated, sent_at: new Date().toISOString() } };
});

const appUrl = 'https://exportflow-lovat.vercel.app';
return [{
  json: {
    appUrl,
    secret: '',
    step: 'followup_1',
    after_days: 3,
    from_status: 'initial_sent',
    to_status: 'followup_1_pending'
  }
}];

const appUrl = 'https://exportflow-lovat.vercel.app';
return [{
  json: {
    appUrl,
    secret: '',
    step: 'followup_2',
    after_days: 7,
    from_status: 'followup_1_sent',
    to_status: 'followup_2_pending'
  }
}];

const appUrl = String($env.EXPORTFLOW_APP_URL || '').replace(/\/+$/, '');
if (!appUrl) throw new Error('Missing EXPORTFLOW_APP_URL in n8n environment.');
return [{ json: { appUrl, secret: $env.N8N_WEBHOOK_SECRET || '', rebuilt_at: new Date().toISOString() } }];
